let e=require("electron");var t={};for(let e of process.argv)if(e.startsWith(`--isis-code=`))t.code=e.slice(12);else if(e.startsWith(`--isis-pin=`))t.pin=e.slice(11);else if(e.startsWith(`--isis-session-ttl=`)){let n=Number(e.slice(19));Number.isFinite(n)&&n>0&&(t.sessionTtl=n)}else e===`--isis-simulate-video`?t.simulateVideo=!0:e===`--isis-simulate-audio`?t.simulateAudio=!0:e===`--isis-fake-input`&&(t.fakeInput=!0);e.contextBridge.exposeInMainWorld(`isis`,{...t,getScreenSourceId:()=>e.ipcRenderer.invoke(`isis:get-screen-source`),sendInput:t=>{e.ipcRenderer.send(`isis:input`,t)},readClipboard:()=>e.ipcRenderer.invoke(`isis:clipboard-read`),writeClipboard:t=>e.ipcRenderer.invoke(`isis:clipboard-write`,t)});